import sys
from pathlib import Path

# Ensure the capstone-project directory is in the Python path
sys.path.append(str(Path(__file__).resolve().parent))

from orchestration.graph import run_telecom_assistant


def call_api(prompt, options, context):
    """
    Promptfoo Python provider entrypoint.
    The 'prompt' parameter contains the evaluated prompt string from promptfoo.yaml.
    """
    try:
        user_query = prompt

        # Run the multi-agent graph with the user query
        result = run_telecom_assistant(user_query)

        # Extract the final response generated by CrewAI
        final_response = result.get("final_response", "")

        return {"output": final_response}
    except Exception as e:
        return {"error": str(e)}
